import React, { useState, useEffect, useMemo } from 'react';
import { 
  Printer, 
  Bus, 
  CheckCircle2, 
  MessageCircle, 
  Zap, 
  ShieldCheck, 
  Building2, 
  Home, 
  Truck, 
  Target, 
  ArrowRight,
  ChevronRight,
  Briefcase,
  Users,
  School,
  FileText,
  DollarSign,
  Info,
  ShieldAlert,
  Clock,
  Flame,
  Mountain,
  Tent,
  Compass,
  Award
} from 'lucide-react';
import { CATEGORIES, Program } from './AdventureBuilder';
import { BookingContextData } from '../App';
import Logo from '../components/Logo';
import { ClientType } from '../types';

// --- CROSS CONNECT AFRICA: ELITE QUOTATION ENGINE V5 ---

const ACCOMMODATION_LEVELS = {
  none: { id: 'none', label: 'N/A (Day Program)', school: 0, corporate: 0, desc: 'Single day engagement.' },
  budget: { id: 'budget', label: 'Budget / Dorms', school: 6500, corporate: 6500, desc: 'Ideal for large youth groups.' },
  mid: { id: 'mid', label: 'Mid-range Lodge', school: 9500, corporate: 9500, desc: 'Comfortable ensuite bush lodges.' },
  premium: { id: 'premium', label: 'Premium Resort', school: 22000, corporate: 22000, desc: 'High-end retreats.' }
};

const FLEET_SOLUTIONS = {
  none: { id: 'none', label: 'Self Drive', price: 0, desc: 'Client arranges own transport.' },
  van: { id: 'van', label: '14-Seater Van', price: 15000, desc: 'Standard group van.' },
  bus_med: { id: 'bus_med', label: '22-33 Seater', price: 23000, desc: 'Medium group bus.' },
  coach: { id: 'coach', label: '51-Seater Coach', price: 31000, desc: 'Large group coach.' },
  cruiser: { id: 'cruiser', label: '4x4 Cruiser', price: 38000, desc: 'Safari Land Cruiser.' },
  safari_van: { id: 'safari_van', label: 'Safari Van', price: 42000, desc: 'Professional safari van.' }
};

const ADD_ONS = [
  { id: 'cert', label: 'Certification', school: 350, corporate: 1200, type: 'PER_PAX' },
  { id: 'aed', label: 'AED/CPR Enhancement', school: 1500, corporate: 2500, type: 'PER_PAX' },
  { id: 'meals', label: 'Meals & Snacks', school: 800, corporate: 1200, type: 'PER_PAX_DAY' },
  { id: 'materials', label: 'Branded Materials', school: 600, corporate: 1200, type: 'PER_PAX' },
  { id: 'report', label: 'Leadership Report', school: 15000, corporate: 25000, type: 'FLAT' },
  { id: 'mc_add', label: 'MC + Event Manager', school: 35000, corporate: 55000, type: 'FLAT' },
  { id: 'transport_pp', label: 'Transport Contribution', school: 1100, corporate: 2500, type: 'PER_PAX' }
];

interface StrategyPreset {
  id: string;
  label: string;
  clientType: ClientType;
  programId: string;
  pax: number;
  accommodation: keyof typeof ACCOMMODATION_LEVELS;
  transport: keyof typeof FLEET_SOLUTIONS;
  addons: string[];
}

const STRATEGY_PRESETS: StrategyPreset[] = [
  { id: 'safety_standard', label: 'Safety Pack (25 Pax)', clientType: 'corporate', programId: 'first_aid', pax: 25, accommodation: 'none', transport: 'none', addons: ['cert', 'aed'] },
  { id: 'corp_standard', label: 'Corp Synergy (20 Pax)', clientType: 'corporate', programId: 'corporate_tb', pax: 20, accommodation: 'none', transport: 'none', addons: ['report'] },
  { id: 'school_standard', label: 'School Mission (50 Pax)', clientType: 'school', programId: 'school_tb', pax: 50, accommodation: 'none', transport: 'none', addons: ['meals', 'transport_pp', 'cert'] },
  { id: 'retreat_standard', label: 'Leader Retreat (15 Pax)', clientType: 'corporate', programId: 'leadership_retreat', pax: 15, accommodation: 'mid', transport: 'bus_med', addons: ['meals'] },
  { id: 'expedition_standard', label: 'Wild Expedition (20 Pax)', clientType: 'corporate', programId: 'overnight_expedition', pax: 20, accommodation: 'none', transport: 'cruiser', addons: ['meals'] },
];

const Calculator: React.FC<{ initialData?: BookingContextData | null }> = ({ initialData }) => {
  const [clientType, setClientType] = useState<ClientType>('corporate');
  const [selectedProgram, setSelectedProgram] = useState<Program>(CATEGORIES[1].programs[0]); 
  const [durationIdx, setDurationIdx] = useState(0);
  const [pax, setPax] = useState(25);
  const [accommodation, setAccommodation] = useState<keyof typeof ACCOMMODATION_LEVELS>('none');
  const [transport, setTransport] = useState<keyof typeof FLEET_SOLUTIONS>('none');
  const [activeAddons, setActiveAddons] = useState<string[]>([]);
  const [activeStrategy, setActiveStrategy] = useState<string | null>(null);

  const [companyInfo, setCompanyInfo] = useState({
    companyName: '',
    contactPerson: '',
    phone: '',
    email: ''
  });

  useEffect(() => {
    if (initialData) {
      if (initialData.program) setSelectedProgram(initialData.program);
      if (initialData.pax) setPax(initialData.pax);
      if (initialData.durationIndex !== undefined) setDurationIdx(initialData.durationIndex);
      if (initialData.categoryTitle?.toLowerCase().includes('school')) setClientType('school');
    }
  }, [initialData]);

  const applyStrategy = (strat: StrategyPreset) => {
    const program = CATEGORIES.flatMap(c => c.programs).find(p => p.id === strat.programId);
    if (!program) return;

    setClientType(strat.clientType);
    setSelectedProgram(program);
    setPax(strat.pax);
    setAccommodation(strat.accommodation);
    setTransport(strat.transport);
    setActiveAddons(strat.addons);
    setActiveStrategy(strat.label);
    setDurationIdx(0); // Reset duration to default for strategy

    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const formatCurrency = (amount: number) => 
    `KES ${amount.toLocaleString()}`;

  const calculationResults = useMemo(() => {
    const tier = selectedProgram.durations ? selectedProgram.durations[durationIdx] : { price: selectedProgram.basePrice, days: 1, label: 'Standard' };
    const days = tier.days;
    const nights = Math.max(0, days - 1);

    let serviceBaseCost = 0;
    let rateAppliedLabel = "";

    if (selectedProgram.priceType === 'flat_rate') {
      serviceBaseCost = tier.price;
      rateAppliedLabel = "Flat Fee";
    } else {
      const ppPrice = tier.price;
      const ppTotal = ppPrice * pax;

      let groupRate = Infinity;
      if (selectedProgram.id === 'first_aid') {
        if (pax >= 40) groupRate = 185000;
        else if (pax >= 25) groupRate = 145000;
        else if (pax >= 10) groupRate = 60000;
      } else if (selectedProgram.id === 'corporate_tb') {
        if (pax >= 35) groupRate = 220000;
        else if (pax >= 20) groupRate = 145000;
        else if (pax >= 10) groupRate = 90000;
      } else if (selectedProgram.id === 'school_tb') {
        if (pax >= 50) groupRate = 220000;
      }

      if (groupRate < ppTotal) {
        serviceBaseCost = groupRate;
        rateAppliedLabel = `Group Flat Rate (${formatCurrency(groupRate)})`;
      } else {
        serviceBaseCost = ppTotal;
        rateAppliedLabel = `${formatCurrency(ppPrice)} pp`;
      }
    }

    const logisticsAccom = ACCOMMODATION_LEVELS[accommodation][clientType] * pax * nights;
    const logisticsTransport = FLEET_SOLUTIONS[transport].price * days;

    let addonsTotal = 0;
    const addonDetails = activeAddons.map(id => {
      const item = ADD_ONS.find(a => a.id === id);
      if (!item) return null;
      let cost = 0;
      if (item.type === 'PER_PAX') cost = item[clientType] * pax;
      else if (item.type === 'PER_PAX_DAY') cost = item[clientType] * pax * days;
      else cost = item[clientType];
      addonsTotal += cost;
      return { label: item.label, cost, type: item.type, rate: item[clientType] };
    }).filter(x => x !== null);

    let opsSafety = 0;
    let opsTierLabel = "Standard Coverage";
    if (pax <= 20) { opsSafety = 8000; opsTierLabel = "Small Group Coverage"; }
    else if (pax <= 50) { opsSafety = 15000; opsTierLabel = "Medium Group Coverage"; }
    else { opsSafety = 25000; opsTierLabel = "Large Group Coverage"; }

    const subtotal = serviceBaseCost + logisticsAccom + logisticsTransport + addonsTotal + opsSafety;
    const deposit = subtotal * 0.5;
    const balance = subtotal - deposit;

    return { 
        serviceBaseCost, rateAppliedLabel, logisticsAccom, logisticsTransport, 
        addonsTotal, addonDetails, opsSafety, opsTierLabel, subtotal, deposit, balance, days, nights, tierLabel: tier.label 
    };
  }, [clientType, selectedProgram, durationIdx, pax, accommodation, transport, activeAddons]);

  const handleWhatsApp = () => {
    if (!companyInfo.companyName) {
      alert("Please provide the organization name for the proposal.");
      return;
    }
    const message = `*CCA INVESTMENT PROPOSAL (V5)*\n--------------------------------\n*Org:* ${companyInfo.companyName}\n*Strategy:* ${activeStrategy || 'Custom'}\n*Program:* ${selectedProgram.title}\n*Pax:* ${pax}\n*Total Investment:* ${formatCurrency(calculationResults.subtotal)}\n*Deposit (50%):* ${formatCurrency(calculationResults.deposit)}\n--------------------------------\nRequesting formal review from CCA Operations.`;
    window.open(`https://wa.me/254710974670?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen bg-brand-cream pt-32 pb-20 px-4 md:px-6">
      <div className="max-w-7xl mx-auto flex flex-col lg:flex-row gap-12 mb-24">

        {/* SIDEBAR CONFIGURATOR */}
        <div className="lg:w-[55%] space-y-8 print:hidden">
          <div className="bg-white p-10 rounded-[2.5rem] shadow-2xl border border-brand-green/5 space-y-12 max-h-[90vh] overflow-y-auto no-scrollbar">

            <header>
               <h2 className="text-3xl font-serif font-bold text-brand-green mb-2">Program Architect</h2>
               <p className="text-gray-400 text-[11px] uppercase tracking-widest font-bold">Quotation Engine V.5.0</p>
            </header>

            {/* STRATEGY PRESETS */}
            <div className="space-y-6">
               <label className="text-[11px] font-bold text-brand-gold uppercase tracking-[0.3em] flex items-center gap-2">
                  <Award size={16}/> Quick Strategy Sync
               </label>
               <div className="flex flex-wrap gap-2">
                  {STRATEGY_PRESETS.map(strat => (
                    <button 
                      key={strat.id} 
                      onClick={() => applyStrategy(strat)}
                      className={`px-4 py-2.5 rounded-full text-[10px] font-bold uppercase tracking-widest transition-all border flex items-center gap-2 ${
                        activeStrategy === strat.label 
                        ? 'bg-brand-gold text-brand-green border-brand-gold' 
                        : 'bg-white text-gray-400 border-gray-100 hover:border-brand-gold/30'
                      }`}
                    >
                      <Zap size={12} /> {strat.label}
                    </button>
                  ))}
                  <button 
                    onClick={() => { setActiveStrategy(null); setActiveAddons([]); }} 
                    className="px-4 py-2.5 rounded-full text-[10px] font-bold uppercase tracking-widest text-gray-300 border border-transparent hover:text-red-400 transition-all"
                  >
                    Reset
                  </button>
               </div>
            </div>

            {/* Client Identity */}
            <div className="space-y-6">
               <label className="text-[11px] font-bold text-brand-gold uppercase tracking-[0.3em] flex items-center gap-2">
                  <Users size={16}/> Client Tier
               </label>
               <div className="flex bg-gray-50 p-2 rounded-2xl">
                  <button onClick={() => { setClientType('school'); setActiveStrategy(null); }} className={`flex-1 py-5 px-6 rounded-xl text-[11px] font-bold uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${clientType === 'school' ? 'bg-brand-green text-brand-gold shadow-lg' : 'text-gray-400'}`}>
                      <School size={18} /> Students / Youth
                  </button>
                  <button onClick={() => { setClientType('corporate'); setActiveStrategy(null); }} className={`flex-1 py-5 px-6 rounded-xl text-[11px] font-bold uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${clientType === 'corporate' ? 'bg-brand-green text-brand-gold shadow-lg' : 'text-gray-400'}`}>
                      <Briefcase size={18} /> Corporate / Adults
                  </button>
               </div>
            </div>

            {/* Program Selection */}
            <div className="space-y-6">
               <label className="text-[11px] font-bold text-brand-gold uppercase tracking-[0.3em] flex items-center gap-2">
                  <Target size={16}/> Mission Objective
               </label>
               <select 
                  value={selectedProgram.id} 
                  onChange={(e) => {
                      const found = CATEGORIES.flatMap(c => c.programs).find(p => p.id === e.target.value);
                      if (found) { setSelectedProgram(found); setDurationIdx(0); setActiveStrategy(null); }
                  }}
                  className="w-full p-6 bg-gray-50 border-none rounded-2xl text-[12px] font-bold uppercase tracking-wider focus:ring-1 focus:ring-brand-green shadow-sm"
               >
                  {CATEGORIES.map(cat => (
                    <optgroup key={cat.id} label={cat.title}>
                        {cat.programs.map(prog => (
                            <option key={prog.id} value={prog.id}>{prog.title}</option>
                        ))}
                    </optgroup>
                  ))}
               </select>
            </div>

            {/* Pax & Duration */}
            <div className="grid grid-cols-2 gap-8">
               <div className="space-y-4">
                  <label className="text-[11px] font-bold text-brand-gold uppercase tracking-[0.3em]">Participants</label>
                  <input type="number" min="1" max="500" value={pax} onChange={(e) => { setPax(parseInt(e.target.value) || 1); setActiveStrategy(null); }} className="w-full p-6 bg-gray-50 border-none rounded-2xl text-lg font-bold focus:ring-1 focus:ring-brand-green shadow-sm" />
               </div>
               <div className="space-y-4">
                  <label className="text-[11px] font-bold text-brand-gold uppercase tracking-[0.3em]">Timeline</label>
                  <select value={durationIdx} onChange={(e) => { setDurationIdx(parseInt(e.target.value)); setActiveStrategy(null); }} className="w-full p-6 bg-gray-50 border-none rounded-2xl text-[12px] font-bold uppercase focus:ring-1 focus:ring-brand-green shadow-sm">
                     {selectedProgram.durations?.map((d, i) => (
                        <option key={i} value={i}>{d.label}</option>
                     )) || <option value={0}>Standard</option>}
                  </select>
               </div>
            </div>

            {/* Logistics Section */}
            <div className="space-y-10 pt-6 border-t border-gray-100">
               <div>
                  <label className="text-[11px] font-bold text-brand-gold uppercase tracking-[0.3em] mb-6 flex items-center gap-2"><Home size={16}/> Base of Operations</label>
                  <div className="grid grid-cols-1 gap-3">
                     {Object.values(ACCOMMODATION_LEVELS).map(acc => (
                        <button key={acc.id} onClick={() => { setAccommodation(acc.id as any); setActiveStrategy(null); }} className={`w-full text-left p-5 rounded-2xl border-2 transition-all flex justify-between items-center ${accommodation === acc.id ? 'bg-brand-green text-brand-gold border-brand-green shadow-xl scale-[1.01]' : 'bg-gray-50 text-gray-400 border-transparent hover:bg-gray-100'}`}>
                           <div className="flex flex-col">
                              <span className="text-[12px] font-bold uppercase tracking-widest">{acc.label}</span>
                              <span className="text-[10px] opacity-60 italic">{acc.desc}</span>
                           </div>
                           {acc.school > 0 && <span className="text-[11px] font-bold">{formatCurrency(acc[clientType])}/n</span>}
                        </button>
                     ))}
                  </div>
               </div>
               <div>
                  <label className="text-[11px] font-bold text-brand-gold uppercase tracking-[0.3em] mb-6 flex items-center gap-2"><Truck size={16}/> Fleet Logistics</label>
                  <div className="grid grid-cols-2 gap-4">
                     {Object.values(FLEET_SOLUTIONS).map(trans => (
                        <button key={trans.id} onClick={() => { setTransport(trans.id as any); setActiveStrategy(null); }} className={`p-5 rounded-2xl border-2 transition-all text-left ${transport === trans.id ? 'bg-brand-green text-brand-gold border-brand-green shadow-xl' : 'bg-gray-50 text-gray-400 border-transparent hover:bg-gray-100'}`}>
                           <div className="text-[11px] font-bold uppercase tracking-wider">{trans.label}</div>
                           <div className="text-[10px] mt-1 opacity-60">{trans.price > 0 ? `${formatCurrency(trans.price)}/day` : 'Client Arranged'}</div>
                        </button>
                     ))}
                  </div>
               </div>
            </div>

            {/* Add-ons */}
            <div className="space-y-6">
               <label className="text-[11px] font-bold text-brand-gold uppercase tracking-[0.3em] flex items-center gap-2"><Zap size={16}/> Strategic Enhancements</label>
               <div className="grid grid-cols-2 gap-4">
                  {ADD_ONS.map(addon => (
                     <button key={addon.id} onClick={() => { setActiveAddons(prev => prev.includes(addon.id) ? prev.filter(x => x !== addon.id) : [...prev, addon.id]); setActiveStrategy(null); }} className={`p-5 rounded-2xl border-2 text-[11px] font-bold uppercase text-left transition-all ${activeAddons.includes(addon.id) ? 'bg-brand-gold/10 border-brand-gold text-brand-green shadow-md' : 'bg-gray-50 border-transparent text-gray-400 hover:bg-gray-100'}`}>
                        {addon.label}
                        <div className="text-[9px] opacity-50 mt-1">{formatCurrency(addon[clientType])} {addon.type === 'FLAT' ? '(Fixed)' : '(Per Pax)'}</div>
                     </button>
                  ))}
               </div>
            </div>

            {/* Organization Info */}
            <div className="space-y-6 pt-8 border-t border-gray-100">
               <label className="text-[11px] font-bold text-brand-gold uppercase tracking-[0.3em] flex items-center gap-2"><Building2 size={16}/> Partner Entity</label>
               <input 
                  type="text" 
                  placeholder="Organization Name (e.g. Safaricom PLC)" 
                  value={companyInfo.companyName} 
                  onChange={(e) => setCompanyInfo({...companyInfo, companyName: e.target.value})} 
                  className="w-full p-6 bg-gray-50 border-none rounded-2xl text-lg font-bold focus:ring-1 focus:ring-brand-green shadow-sm" 
               />
            </div>
          </div>
        </div>

        {/* QUOTE OUTPUT */}
        <div className="lg:w-[45%]">
          <div className="sticky top-32">
            <div id="quote-document" className="bg-white shadow-[0_40px_100px_rgba(0,0,0,0.1)] rounded-none min-h-[1000px] flex flex-col border border-gray-100 relative overflow-hidden animate-fade-in-up" style={{ backgroundImage: "url('https://www.transparenttextures.com/patterns/paper-fibers.png')", backgroundColor: '#fff', transform: 'scale(0.98)', transformOrigin: 'top center' }}>

               {/* WATERMARK */}
               <div className="absolute inset-0 flex items-center justify-center opacity-[0.02] pointer-events-none rotate-[25deg] select-none">
                  <span className="text-8xl md:text-[12rem] font-serif font-bold text-brand-green uppercase tracking-tighter">CROSS CONNECT</span>
               </div>

               {/* HEADER */}
               <div className="p-8 md:p-12 border-b-8 border-brand-green bg-brand-cream/50 relative z-10">
                  <div className="flex justify-between items-start mb-12">
                     <div className="flex items-center gap-4">
                        <Logo className="w-16 h-16" />
                        <div>
                           <h2 className="text-2xl font-serif font-bold text-brand-green tracking-tighter uppercase leading-none">Cross Connect</h2>
                           <span className="text-brand-gold text-[0.6rem] tracking-[0.4em] uppercase font-bold block mt-1">Adventure Management</span>
                        </div>
                     </div>
                     <div className="text-right text-[9px] text-gray-400 font-bold uppercase tracking-[0.3em] leading-relaxed">
                        Ref: PROP-{new Date().getFullYear()}-{Math.floor(Math.random() * 9000) + 1000}<br/>
                        Nairobi Base
                     </div>
                  </div>

                  <div className="flex flex-col justify-between items-start gap-6">
                     <div>
                        <div className="flex items-center gap-2 mb-2">
                          <span className="text-brand-gold text-[9px] font-bold uppercase tracking-[0.4em] block">Mission Strategy For</span>
                          {activeStrategy && (
                            <span className="bg-brand-green text-brand-gold text-[7px] px-2 py-0.5 rounded-full font-bold uppercase tracking-widest flex items-center gap-1 shadow-sm">
                              <Award size={8} /> Institutional Tier: {activeStrategy}
                            </span>
                          )}
                        </div>
                        <h3 className="text-3xl font-serif font-bold text-brand-green italic underline decoration-brand-gold/20 underline-offset-[10px]">
                           {companyInfo.companyName || 'Valued Partner'}
                        </h3>
                     </div>
                     <div className="flex gap-8 bg-white/80 backdrop-blur-md p-4 rounded-2xl border border-brand-green/10 shadow-sm w-full justify-around">
                        <div className="text-center">
                           <div className="text-[8px] text-gray-400 uppercase font-bold mb-1">Pax</div>
                           <div className="text-2xl font-serif font-bold text-brand-green">{pax}</div>
                        </div>
                        <div className="w-px h-8 bg-gray-100 my-auto"></div>
                        <div className="text-center">
                           <div className="text-[8px] text-gray-400 uppercase font-bold mb-1">Duration</div>
                           <div className="text-2xl font-serif font-bold text-brand-green">{calculationResults.days}d</div>
                        </div>
                     </div>
                  </div>
               </div>

               {/* TABLE CONTENT */}
               <div className="p-8 md:p-12 flex-grow space-y-12 relative z-10">
                  <section>
                     <div className="flex items-center gap-3 mb-6 border-b-2 border-brand-green/5 pb-3">
                        <FileText size={16} className="text-brand-gold"/>
                        <h4 className="text-[10px] font-bold uppercase tracking-[0.4em] text-brand-green">Investment Schedule</h4>
                     </div>

                     <table className="w-full text-left">
                        <thead>
                           <tr className="text-[9px] text-gray-400 uppercase tracking-widest border-b border-gray-50">
                              <th className="py-4 font-bold">Component</th>
                              <th className="py-4 font-bold text-right">Subtotal</th>
                           </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-50">
                           {/* Core Service */}
                           <tr>
                              <td className="py-6">
                                 <div className="font-bold text-brand-green text-base">{selectedProgram.title}</div>
                                 <div className="text-[9px] text-gray-400 uppercase mt-1">{calculationResults.rateAppliedLabel}</div>
                              </td>
                              <td className="py-6 text-right font-serif font-bold text-brand-green text-base">{formatCurrency(calculationResults.serviceBaseCost)}</td>
                           </tr>

                           {/* Logistics Accom */}
                           {calculationResults.logisticsAccom > 0 && (
                              <tr>
                                 <td className="py-6">
                                    <div className="font-bold text-brand-green text-base">Facility Logistics</div>
                                    <div className="text-[9px] text-gray-400 uppercase mt-1">{ACCOMMODATION_LEVELS[accommodation].label}</div>
                                 </td>
                                 <td className="py-6 text-right font-serif font-bold text-brand-green text-base">{formatCurrency(calculationResults.logisticsAccom)}</td>
                              </tr>
                           )}

                           {/* Transport */}
                           {calculationResults.logisticsTransport > 0 && (
                              <tr>
                                 <td className="py-6">
                                    <div className="font-bold text-brand-green text-base">Field Mobility</div>
                                    <div className="text-[9px] text-gray-400 uppercase mt-1">{FLEET_SOLUTIONS[transport].label}</div>
                                 </td>
                                 <td className="py-6 text-right font-serif font-bold text-brand-green text-base">{formatCurrency(calculationResults.logisticsTransport)}</td>
                              </tr>
                           )}

                           {/* Add-ons */}
                           {calculationResults.addonDetails.map((addon, idx) => (
                               <tr key={idx}>
                                  <td className="py-6">
                                     <div className="font-bold text-brand-green text-base">{addon.label}</div>
                                     <div className="text-[9px] text-gray-400 uppercase mt-1">Enhancement</div>
                                  </td>
                                  <td className="py-6 text-right font-serif font-bold text-brand-green text-base">{formatCurrency(addon.cost)}</td>
                               </tr>
                           ))}

                           {/* Ops & Safety */}
                           <tr className="bg-brand-sand/20">
                              <td className="py-6 px-3">
                                 <div className="font-bold text-brand-green text-base">Ops & Safety</div>
                                 <div className="text-[9px] text-gray-400 uppercase mt-1 flex items-center gap-2">
