      >
        <ShoppingBag size={24} />
        {cart.length > 0 && <span className="bg-brand-gold text-brand-green text-[10px] font-bold px-2 py-0.5 rounded-full">{cart.reduce((a, b) => a + b.quantity, 0)}</span>}
