                 <input 
                    type="text" 
                    placeholder="Search archives..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full pl-12 pr-6 py-5 bg-white border border-gray-100 rounded-2xl text-xs font-bold uppercase tracking-widest focus:border-brand-green focus:ring-1 focus:ring-brand-green transition-all shadow-sm"
                 />
                 <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-brand-gold" />
              </div>

              {/* Filters */}
              <div className="space-y-4">
                 <label className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.4em] mb-4 block">Categories</label>
                 <div className="flex flex-col gap-2">
                    {categories.map(cat => (
                        <button
                          key={cat}
                          onClick={() => setSelectedCategory(cat)}
                          className={`text-left px-6 py-4 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all flex justify-between items-center ${
                            selectedCategory === cat 
                              ? 'bg-brand-green text-brand-gold shadow-xl' 
                              : 'text-gray-400 hover:bg-white hover:text-brand-green'
                          }`}
                        >
                          {cat}
                          {selectedCategory === cat && <ChevronRight size={14} />}
                        </button>
                    ))}
                 </div>
              </div>

              {/* Member Promo */}
              <div className="bg-brand-sand p-8 rounded-3xl border border-brand-green/5 relative overflow-hidden group">
