                 <p className="text-xs text-gray-500 font-medium leading-relaxed relative z-10 italic">"Active mission participants receive an automated 15% discount on all field gear."</p>
              </div>
           </div>
        </div>

        {/* PRODUCTS GRID */}
        <div className="flex-grow">
           <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-12">
              {filteredProducts.map(product => (
                <div 
                  key={product.id} 
                  onClick={() => setSelectedProduct(product)}
                  className="group bg-white rounded-none border border-transparent hover:border-gray-100 hover:shadow-[0_40px_100px_rgba(0,0,0,0.05)] transition-all duration-700 flex flex-col cursor-pointer"
