                      <div className="absolute top-6 right-6 translate-x-4 opacity-0 group-hover:translate-x-0 group-hover:opacity-100 transition-all duration-500">
                         <div className="bg-white/90 backdrop-blur-md px-4 py-2 text-[10px] font-bold text-brand-green uppercase tracking-[0.3em] shadow-xl">
                            {formatPrice(product.price)}
                         </div>
                      </div>
                   </div>
                   <div className="p-8 space-y-4">
                      <div className="text-[9px] text-brand-gold font-bold uppercase tracking-[0.4em]">{product.category}</div>
                      <h3 className="font-serif text-2xl font-bold text-brand-green tracking-tight leading-none group-hover:italic transition-all">{product.name}</h3>
                      <p className="text-gray-400 text-sm font-serif italic line-clamp-2 leading-relaxed opacity-70">"{product.description}"</p>
                      <div className="pt-4 flex justify-between items-center opacity-0 group-hover:opacity-100 translate-y-2 group-hover:translate-y-0 transition-all duration-500">
                         <span className="text-[10px] font-bold uppercase tracking-widest text-brand-green flex items-center gap-2">View Archive <ArrowRight size={14}/></span>
                         <Plus size={20} className="text-brand-gold"/>
                      </div>
                   </div>
                </div>
              ))}
           </div>
        </div>
      </div>

      {/* PRODUCT DETAIL MODAL */}
      {selectedProduct && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-6 bg-brand-green/95 backdrop-blur-xl animate-fade-in-up">
           <div className="bg-white rounded-[2rem] overflow-hidden shadow-2xl max-w-5xl w-full grid grid-cols-1 lg:grid-cols-2 max-h-[90vh] overflow-y-auto border border-white/20">
              <div className="bg-brand-sand relative">
                 <img src={selectedProduct.image} alt={selectedProduct.name} className="w-full h-full object-cover" />
                 <button onClick={() => setSelectedProduct(null)} className="absolute top-6 left-6 lg:hidden bg-white/20 p-3 rounded-full backdrop-blur-md"><X size={20}/></button>
