                          "{selectedProduct.valueProp}"
                       </div>
                    </div>
                 </div>

                 <button 
                    onClick={() => addToCart(selectedProduct)}
                    className="w-full mt-12 py-8 bg-brand-green text-brand-gold font-bold uppercase tracking-[0.6em] text-[10px] hover:scale-[1.02] active:scale-95 transition-all shadow-2xl flex items-center justify-center gap-4"
                 >
                    <ShoppingCart size={20} /> Add to Mission Bag
                 </button>
              </div>
           </div>
        </div>
      )}

      {/* CART SIDEBAR - PREMIUM DRAWER */}
      <div className={`fixed inset-y-0 right-0 z-[100] w-full md:w-[450px] bg-white shadow-2xl transform transition-transform duration-700 cubic-bezier(0.16, 1, 0.3, 1) flex flex-col ${isCartOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="p-10 bg-brand-green text-white flex justify-between items-center border-b border-white/5">
            <h2 className="text-3xl font-serif font-bold flex items-center gap-4 italic tracking-tighter">
                <ShoppingBag size={24} className="text-brand-gold"/> Mission Bag
            </h2>
            <button onClick={() => setIsCartOpen(false)} className="hover:text-brand-gold transition-colors"><X size={32} /></button>
        </div>

        <div className="flex-grow overflow-y-auto p-10 space-y-10">
            {cart.length === 0 ? (
                <div className="text-center text-gray-300 py-32 space-y-6">
                    <Package size={80} className="mx-auto opacity-10" />
                    <p className="font-serif italic text-2xl">"Your mission bag is empty."</p>
                    <button onClick={() => setIsCartOpen(false)} className="text-[10px] font-bold uppercase tracking-[0.4em] text-brand-gold border-b border-brand-gold pb-1">Continue Exploration</button>
                </div>
            ) : (
                cart.map(item => (
