                            <div className="text-[10px] font-bold uppercase text-gray-400 tracking-widest">{formatPrice(item.price)}</div>
                            <div className="flex items-center gap-6 pt-2">
                                <div className="flex items-center gap-3 bg-gray-50 px-3 py-1.5 rounded-lg">
                                   <button onClick={() => updateQuantity(item.id, -1)} className="hover:text-brand-gold"><Minus size={14} /></button>
                                   <span className="text-sm font-bold w-4 text-center">{item.quantity}</span>
                                   <button onClick={() => updateQuantity(item.id, 1)} className="hover:text-brand-gold"><Plus size={14} /></button>
                                </div>
                                <button onClick={() => removeFromCart(item.id)} className="text-[10px] font-bold uppercase tracking-widest text-red-400 hover:text-red-600 underline underline-offset-4">Remove</button>
                            </div>
                        </div>
                    </div>
                ))
            )}
        </div>

        <div className="p-10 border-t border-gray-100 bg-brand-sand/50">
            <div className="flex justify-between items-end mb-10">
