            >
                <MessageCircle size={20} /> Secure with Consultant
            </button>
        </div>
      </div>

      {isCartOpen && (
        <div onClick={() => setIsCartOpen(false)} className="fixed inset-0 bg-brand-green/80 z-[90] backdrop-blur-md animate-fade-in"></div>
      )}

    </div>
  );
};

