                      <tr><td className="py-6">Field Logistics & Fleet</td><td className="py-6 text-right font-bold tracking-tight">KES {((ACCOMMODATION_LEVELS[accommodation][clientType] * pax * (results.days - 1)) + (FLEET_SOLUTIONS[transport].price * results.days)).toLocaleString()}</td></tr>
