};

const FLEET_SOLUTIONS = {
  none: { id: 'none', label: 'Self Drive', price: 0, desc: 'Client handles mobility.' },
  van: { id: 'van', label: '14-Seater Group Van', price: 15000, desc: 'Standard field van.' },
  bus: { id: 'bus', label: '22–33 Seater Bus', price: 23000, desc: 'Medium group capacity.' },
