  safari_van: { id: 'safari_van', label: 'Safari Field Van', price: 38000, desc: 'Professional tourism van.' }
};

const MC_TIERS = {
  none: { id: 'none', label: 'No MC Hosting', price: 0 },
  standard: { id: 'standard', label: 'Standard MC (4hrs)', price: 35000 },
  premium: { id: 'premium', label: 'Premium Wedding/Church', price: 65000 },
  corporate: { id: 'corporate', label: 'Corporate/Conference MC', price: 125000 },
  celebrity: { id: 'celebrity', label: 'Celebrity / High-profile', price: 250000 }
};

const Calculator: React.FC<{ initialData?: BookingContextData | null }> = ({ initialData }) => {
  const [clientType, setClientType] = useState<ClientType>('corporate');
  const [selectedProgram, setSelectedProgram] = useState<Program>(CATEGORIES[1].programs[0]); 
  const [durationIdx, setDurationIdx] = useState(0);
  const [pax, setPax] = useState(25);
  const [accommodation, setAccommodation] = useState<keyof typeof ACCOMMODATION_LEVELS>('none');
  const [transport, setTransport] = useState<keyof typeof FLEET_SOLUTIONS>('none');
  const [mcType, setMcType] = useState<keyof typeof MC_TIERS>('none');
  const [companyInfo, setCompanyInfo] = useState({ companyName: '', contact: '' });

  useEffect(() => {
    if (initialData) {
      if (initialData.program) setSelectedProgram(initialData.program);
      if (initialData.pax) setPax(initialData.pax);
      if (initialData.durationIndex !== undefined) setDurationIdx(initialData.durationIndex);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  }, [initialData]);

  const results = useMemo(() => {
    const tier = selectedProgram.durations ? selectedProgram.durations[durationIdx] : { price: selectedProgram.basePrice, days: 1 };
    const days = tier.days;
    const baseCost = tier.price * pax;

    // Mandatory Ops & Safety Fee (Varies by scale) - Includes Regulatory compliance, on-ground coordination, etc.
    const opsFee = pax < 20 ? 15000 : pax < 50 ? 35000 : 75000;

    const logistics = (ACCOMMODATION_LEVELS[accommodation][clientType] * pax * Math.max(0, days - 1)) + (FLEET_SOLUTIONS[transport].price * days);
    const mcCost = MC_TIERS[mcType].price;

    const subtotal = baseCost + logistics + mcCost + opsFee;
    return { subtotal, deposit: subtotal * 0.5, opsFee, days };
  }, [clientType, selectedProgram, durationIdx, pax, accommodation, transport, mcType]);

