    const message = `*CCA INVESTMENT PROPOSAL (V.5)*\n--------------------------------\nOrg: ${companyInfo.companyName || 'Valued Partner'}\nObjective: ${selectedProgram.title}\nScale: ${pax} Participants\nTimeline: ${results.days} Day(s)\nLogistics: ${FLEET_SOLUTIONS[transport].label}\nMC Tier: ${MC_TIERS[mcType].label}\n--------------------------------\n*TOTAL INVESTMENT: KES ${results.subtotal.toLocaleString()}*`;
    window.open(`https://wa.me/254710974670?text=${encodeURIComponent(message)}`, '_blank');
  };

