            </header>

            <div className="space-y-12">
               {/* Client Selection */}
               <div>
                  <label className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.6em] mb-6 block">Target Audience</label>
                  <div className="flex bg-gray-50 p-2">
                     <button onClick={() => setClientType('school')} className={`flex-1 py-5 text-[11px] font-bold uppercase tracking-[0.3em] transition-all ${clientType === 'school' ? 'bg-brand-green text-brand-gold shadow-lg' : 'text-gray-400 hover:text-brand-green'}`}>Youth / Schools</button>
                     <button onClick={() => setClientType('corporate')} className={`flex-1 py-5 text-[11px] font-bold uppercase tracking-[0.3em] transition-all ${clientType === 'corporate' ? 'bg-brand-green text-brand-gold shadow-lg' : 'text-gray-400 hover:text-brand-green'}`}>Corporate / Adult</button>
                  </div>
               </div>

               {/* Core Objective */}
               <div>
                  <label className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.6em] mb-6 block">Mission Objective</label>
                  <select 
                     value={selectedProgram.id} 
                     onChange={(e) => {
                        const prog = CATEGORIES.flatMap(c => c.programs).find(p => p.id === e.target.value);
                        if (prog) setSelectedProgram(prog);
                     }}
                     className="w-full p-6 bg-gray-50 border-none text-[12px] font-bold uppercase tracking-wider focus:ring-1 focus:ring-brand-green shadow-sm"
                  >
                     {CATEGORIES.map(cat => (
                        <optgroup key={cat.id} label={cat.title}>
                           {cat.programs.map(p => <option key={p.id} value={p.id}>{p.title}</option>)}
                        </optgroup>
                     ))}
