                  <div>
                     <label className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.6em] mb-6 block">Participants</label>
                     <input type="number" value={pax} onChange={(e) => setPax(parseInt(e.target.value) || 1)} className="w-full p-6 bg-gray-50 border-none font-serif font-bold text-3xl text-brand-green focus:ring-1 focus:ring-brand-green" />
