                   >
                      Formalize Mission Proposal <ArrowRight size={22} className="inline ml-4" />
                   </button>
                </div>
             )}

             {loading && (
                <div className="h-full min-h-[700px] flex flex-col items-center justify-center p-32 bg-white rounded-none shadow-2xl border border-brand-green/5 text-center relative overflow-hidden">
