                   <div className="relative mb-16">
                      <div className="w-64 h-64 border-[3px] border-brand-gold/10 border-t-brand-gold rounded-full animate-spin"></div>
                      <Compass className="absolute inset-0 m-auto text-brand-green animate-pulse" size={80} />
                   </div>
                   <h3 className="text-5xl font-serif text-brand-green font-bold mb-8 italic tracking-tight">Syncing Field Archives...</h3>
                   <p className="text-gray-400 max-w-md italic font-serif text-3xl leading-relaxed opacity-70">
                     "Our Lead Strategist is curating your transformational mission."
                   </p>
                </div>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};

