interface CartItem extends Product {
  quantity: number;
}

const Shop: React.FC = () => {
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const filteredProducts = products.filter(p => {
    const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;
    const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const formatPrice = (price: string) => `KES ${parseInt(price).toLocaleString()}`;

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    setSelectedProduct(null);
    setIsCartOpen(true);
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = item.quantity + delta;
        return newQty > 0 ? { ...item, quantity: newQty } : item;
      }
      return item;
    }));
  };

  const cartTotal = cart.reduce((sum, item) => sum + (parseInt(item.price) * item.quantity), 0);

  const handleCheckout = () => {
    if (cart.length === 0) return;
    let message = `*CCA GEAR ORDER*\n--------------------------------\n`;
    cart.forEach(item => { message += `${item.quantity}x ${item.name}\n`; });
    message += `--------------------------------\n*TOTAL: KES ${cartTotal.toLocaleString()}*`;
    window.open(`https://wa.me/254710974670?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen bg-brand-cream pt-40 pb-32">

      {/* FLOATING CART TRIGGER */}
      <button 
        onClick={() => setIsCartOpen(true)}
        className="fixed bottom-10 right-10 z-40 bg-brand-green text-brand-gold p-6 rounded-full shadow-[0_30px_60px_rgba(2,44,34,0.4)] kinetic-btn flex items-center gap-4 border border-brand-gold/30"
      >
        <ShoppingBag size={24} />
        {cart.length > 0 && <span className="bg-brand-gold text-brand-green text-[10px] font-bold px-2 py-0.5 rounded-full">{cart.reduce((a, b) => a + b.quantity, 0)}</span>}
      </button>

      <div className="max-w-[1600px] mx-auto px-6 md:px-12 flex flex-col lg:flex-row gap-24">

        {/* SIDEBAR */}
