                 <span className="text-brand-gold text-[11px] font-bold uppercase tracking-[0.6em] mb-4 block">Merchant of Merit</span>
                 <h1 className="text-5xl md:text-7xl font-serif font-bold text-brand-green leading-none tracking-tighter italic">Boutique <br/><span className="not-italic text-brand-gold">Gear.</span></h1>
                 <p className="text-gray-400 mt-10 font-serif italic text-xl opacity-80 leading-relaxed">"Equipping the character journey with objects of uncompromising quality."</p>
              </div>

              <div className="relative">
                 <input 
                    type="text" 
                    placeholder="Search archives..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full pl-14 pr-6 py-6 bg-white border border-gray-100 rounded-none text-xs font-bold uppercase tracking-widest focus:ring-1 focus:ring-brand-green shadow-sm"
                 />
                 <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-300" />
              </div>

              <div className="space-y-6">
                 <label className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.4em] block">Categories</label>
                 <div className="flex flex-col gap-3">
                    {categories.map(cat => (
                        <button
                          key={cat}
                          onClick={() => setSelectedCategory(cat)}
                          className={`text-left px-8 py-5 rounded-none text-[11px] font-bold uppercase tracking-widest transition-all flex justify-between items-center ${
                            selectedCategory === cat 
                              ? 'bg-brand-green text-brand-gold shadow-xl' 
                              : 'text-gray-400 hover:text-brand-green'
                          }`}
                        >
                          {cat}
                          {selectedCategory === cat && <ChevronRight size={16} />}
                        </button>
                    ))}
                 </div>
              </div>
           </div>
        </div>

        {/* PRODUCTS GRID */}
        <div className="flex-grow">
           <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-16">
              {filteredProducts.map(product => (
                <div 
                  key={product.id} 
                  onClick={() => setSelectedProduct(product)}
                  className="group bg-white rounded-none border border-transparent hover:shadow-[0_60px_120px_rgba(0,0,0,0.06)] transition-all duration-700 flex flex-col cursor-pointer overflow-hidden"
                >
                   <div className="aspect-[4/5] bg-brand-sand overflow-hidden relative">
                      <img 
                        src={product.image} 
                        alt={product.name} 
                        className="w-full h-full object-cover grayscale group-hover:grayscale-0 group-hover:scale-105 transition-all duration-[3s]" 
                      />
                      <div className="absolute top-8 right-8">
                         <div className="bg-white/90 backdrop-blur-md px-6 py-3 text-[11px] font-bold text-brand-green uppercase tracking-[0.3em] shadow-2xl">
                            {formatPrice(product.price)}
                         </div>
                      </div>
                   </div>
                   <div className="p-10 space-y-6">
                      <div className="text-[10px] text-brand-gold font-bold uppercase tracking-[0.5em]">{product.category}</div>
                      <h3 className="font-serif text-3xl font-bold text-brand-green tracking-tight leading-none italic transition-all">{product.name}</h3>
                      <p className="text-gray-400 text-lg font-serif italic line-clamp-2 leading-relaxed opacity-70">"{product.description}"</p>
