                         <Plus size={24} className="text-brand-gold"/>
                      </div>
                   </div>
                </div>
              ))}
           </div>
        </div>
      </div>

      {/* PRODUCT DETAIL MODAL */}
      {selectedProduct && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-6 bg-brand-green/95 backdrop-blur-2xl animate-fade-in-up">
           <div className="bg-white rounded-none overflow-hidden shadow-2xl max-w-6xl w-full grid grid-cols-1 lg:grid-cols-2 max-h-[95vh] overflow-y-auto border border-white/20">
              <div className="bg-brand-sand relative">
                 <img src={selectedProduct.image} alt={selectedProduct.name} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-[3s]" />
                 <button onClick={() => setSelectedProduct(null)} className="absolute top-8 left-8 lg:hidden bg-white/40 p-4 rounded-full backdrop-blur-md"><X size={24}/></button>
              </div>
              <div className="p-16 md:p-24 flex flex-col justify-between relative">
                 <button onClick={() => setSelectedProduct(null)} className="absolute top-10 right-10 hidden lg:block text-gray-300 hover:text-brand-green transition-colors"><X size={40}/></button>

                 <div className="space-y-12">
                    <div>
                       <span className="text-brand-gold text-[11px] font-bold uppercase tracking-[0.8em] mb-6 block">{selectedProduct.category} Catalog</span>
                       <h2 className="text-6xl font-serif font-bold text-brand-green tracking-tighter leading-none italic">{selectedProduct.name}</h2>
                       <div className="text-4xl font-serif font-bold text-brand-gold mt-10">{formatPrice(selectedProduct.price)}</div>
                    </div>

                    <div className="space-y-8">
                       <p className="text-2xl text-gray-500 font-serif leading-relaxed italic opacity-80 leading-relaxed">"{selectedProduct.description}"</p>
                       <div className="bg-brand-sand p-10 border-l-[6px] border-brand-gold italic font-serif text-brand-green text-xl shadow-sm">
                          <span className="text-[11px] font-bold uppercase tracking-[0.5em] block mb-4 opacity-40">Operational Value</span>
                          "{selectedProduct.valueProp}"
                       </div>
                    </div>
                 </div>

                 <button 
                    onClick={() => addToCart(selectedProduct)}
                    className="w-full mt-16 py-10 bg-brand-green text-brand-gold font-bold uppercase tracking-[0.7em] text-[11px] shadow-2xl kinetic-btn flex items-center justify-center gap-6"
                 >
                    <ShoppingCart size={24} /> SECURE IN BAG
                 </button>
              </div>
           </div>
        </div>
      )}

      {/* CART DRAWER */}
      <div className={`fixed inset-y-0 right-0 z-[100] w-full md:w-[500px] bg-white shadow-2xl transform transition-transform duration-700 cubic-bezier(0.16, 1, 0.3, 1) flex flex-col ${isCartOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="p-12 bg-brand-green text-white flex justify-between items-center">
            <h2 className="text-4xl font-serif font-bold flex items-center gap-6 italic tracking-tighter">
                <ShoppingBag size={32} className="text-brand-gold"/> Mission Bag
            </h2>
            <button onClick={() => setIsCartOpen(false)} className="hover:text-brand-gold transition-colors"><X size={40} /></button>
        </div>

        <div className="flex-grow overflow-y-auto p-12 space-y-12 paper-texture">
            {cart.length === 0 ? (
                <div className="text-center text-gray-300 py-48 space-y-8">
                    <ShoppingBag size={100} className="mx-auto opacity-10" />
                    <p className="font-serif italic text-3xl">"Your bag is empty."</p>
                    <button onClick={() => setIsCartOpen(false)} className="text-[11px] font-bold uppercase tracking-[0.5em] text-brand-gold border-b-2 border-brand-gold pb-2">Continue Discovery</button>
                </div>
            ) : (
                cart.map(item => (
                    <div key={item.id} className="flex gap-10 group animate-reveal">
                        <div className="w-32 h-32 bg-brand-sand overflow-hidden flex-shrink-0 shadow-lg">
                            <img src={item.image} alt={item.name} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-700" />
                        </div>
                        <div className="flex-grow space-y-4">
                            <h4 className="font-serif font-bold text-brand-green text-2xl leading-tight group-hover:text-brand-gold transition-colors italic">{item.name}</h4>
