      if (!selectedAddons.includes(a.id)) return sum;
      return sum + (a.type === 'pp' ? a.price * pax : a.price);
    }, 0);

    const subtotal = baseTotal + venueCost + transportCost + accommodationCost + opsFee + addonsTotal;
