    // Core Base Calculation
    const isActuallyGroup = tier.isGroup || pricingMode === 'group';
    const unitRate = tier.price;
    const baseTotal = isActuallyGroup ? unitRate : unitRate * pax;

    // Logistics
    const venueCost = VENUE_GROUNDS[venue].price * days;
    const transportCost = FLEET_SOLUTIONS[transport].price * days;
    const accommodationCost = ACCOMMODATION_LEVELS[accommodation].price * pax * Math.max(0, days - 1);

    // Admin & Ground Charges (Transparent)
    const groundHandling = pax < 20 ? 8000 : pax < 50 ? 15000 : 30000;
    const adminFees = 5000;
    const setupFees = 5000;

