                </div>
             </footer>
          </div>
        </div>
      </div>

      <style>{`
        @media print {
          body * { visibility: hidden; background-color: white !important; }
          #quote-doc, #quote-doc * { visibility: visible; }
          #quote-doc {
            position: fixed;
            left: 0;
            top: 0;
            width: 100%;
            height: 100%;
            padding: 40px;
            margin: 0;
            box-shadow: none;
            border: none;
          }
          .print\\:hidden { display: none !important; }
        }
      `}</style>
    </div>
  );
};

