                cart.map(item => (
                    <div key={item.id} className="flex gap-6 group animate-reveal border-b border-gray-50 pb-8 last:border-0">
                        <div className="w-20 h-20 bg-brand-sand overflow-hidden flex-shrink-0 shadow-sm">
