    switch (cat) {
      case 'Apparel': return <Tag size={14} />;
      case 'Event Essentials': return <ShoppingBag size={14} />;
      case 'Faith & Devotion': return <Heart size={14} />;
      case 'Safety & First Aid': return <ShieldCheck size={14} />;
      case 'CSR & Impact': return <Heart size={14} />;
      case 'Event Passes': return <Ticket size={14} />;
      default: return null;
    }
