                      </div>
                      <div className="absolute bottom-4 right-4">
                         <div className="bg-white/95 backdrop-blur-md px-4 py-2 text-[10px] font-bold text-brand-green uppercase tracking-[0.2em] shadow-lg">
                            {formatPrice(product.price)}
