    if (cart.length === 0) return;
    let message = `*CCA MERCHANT ORDER*\n--------------------------------\n`;
    cart.forEach(item => { message += `${item.quantity}x ${item.name}\n`; });
    message += `--------------------------------\n*TOTAL: KES ${cartTotal.toLocaleString()}*`;
