    window.open(`https://wa.me/254710974670?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen bg-brand-cream pt-40 pb-32 px-6">
      <div className="max-w-7xl mx-auto">
        <h1 className="text-5xl md:text-7xl font-serif font-bold text-brand-green italic mb-16">Upcoming <br/><span className="not-italic text-brand-gold">Missions.</span></h1>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
          {mockEvents.map(event => (
            <div 
              key={event.id} 
              onClick={() => setSelectedEvent(event)}
              className="group bg-white border border-gray-100 cursor-pointer overflow-hidden hover:shadow-2xl transition-all duration-700"
            >
              <div className="aspect-[16/9] overflow-hidden relative bg-brand-sand flex flex-col items-center justify-center p-8 text-center text-brand-green/20">
                 <CameraOff size={32} className="mb-2" />
                 <span className="text-[8px] font-bold uppercase tracking-widest">Gallery on WhatsApp</span>
                 <div className="absolute top-4 left-4 bg-brand-green text-brand-gold px-3 py-1 text-[9px] font-bold uppercase tracking-widest">{event.month} 2026</div>
              </div>
              <div className="p-8 space-y-4">
                 <h3 className="text-xl font-serif font-bold text-brand-green italic">{event.title}</h3>
                 <div className="flex justify-between items-center text-[10px] font-bold uppercase tracking-widest text-gray-400 pt-4 border-t border-gray-50">
                    <div className="flex items-center gap-2"><MapPin size={12} /> {event.location}</div>
                    <div className="text-brand-green font-serif text-lg font-bold">KES {event.price.toLocaleString()}</div>
                 </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {selectedEvent && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-brand-green/95 backdrop-blur-md">
           <div className="bg-white rounded-none shadow-2xl max-w-4xl w-full max-h-[90vh] overflow-y-auto relative paper-texture">
              <button onClick={() => setSelectedEvent(null)} className="absolute top-6 right-6 p-2 text-gray-400 hover:text-brand-green transition-colors z-20"><X size={32}/></button>
              <div className="grid grid-cols-1 md:grid-cols-2">
                 <div className="aspect-[4/5] md:aspect-auto bg-brand-sand flex flex-col items-center justify-center p-12 text-center text-brand-green/20 border-r border-gray-50">
                    <CameraOff size={64} className="mb-4" />
                    <span className="text-xs font-bold uppercase tracking-[0.3em]">Session photos on request</span>
                 </div>
                 <div className="p-10 space-y-8">
                    <h2 className="text-3xl font-serif font-bold text-brand-green italic">{selectedEvent.title}</h2>
                    <p className="text-gray-500 font-serif italic text-sm">"{selectedEvent.description}"</p>
                    <div className="space-y-4 pt-6 border-t border-gray-100">
                       <h4 className="text-[10px] font-bold text-brand-gold uppercase tracking-[0.4em]">Field Protocol</h4>
                       <div className="space-y-3">
                          {selectedEvent.itinerary.map((step, i) => (
                             <div key={i} className="flex gap-4">
                                <span className="text-[9px] font-bold text-brand-gold uppercase tracking-widest">{step.time}</span>
                                <span className="text-xs font-serif italic text-brand-green">{step.task}</span>
                             </div>
                          ))}
                       </div>
                    </div>
                    <button 
                      onClick={() => handleBooking(selectedEvent)}
                      className="w-full py-5 bg-brand-green text-brand-gold font-bold uppercase tracking-[0.4em] text-[10px] shadow-xl flex items-center justify-center gap-4 mt-8"
                    >
                      Secure Slot <Zap size={16}/>
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};
